public class TimelineBar : Control {
 int position;public int Minimum{get;set;}public int Maximum{get;set;}public TickStyle TickStyle{get;set;}
 public int Value{get{return position;}set{position=Math.Max(Minimum,Math.Min(Maximum,value));Invalidate();}}
 public TimelineBar(){Maximum=1000;Height=32;DoubleBuffered=true;SetStyle(ControlStyles.Selectable,true);TabStop=true;Cursor=Cursors.Hand;AccessibleName="Posição do vídeo";}
 void SeekAt(int x){if(Enabled)Value=Minimum+(int)((double)Math.Max(0,Math.Min(Width-16,x-8))/Math.Max(1,Width-16)*(Maximum-Minimum));}
 protected override void OnMouseDown(MouseEventArgs e){Focus();Capture=true;SeekAt(e.X);base.OnMouseDown(e);}
 protected override void OnMouseMove(MouseEventArgs e){if(Capture)SeekAt(e.X);base.OnMouseMove(e);}
 protected override void OnMouseUp(MouseEventArgs e){SeekAt(e.X);Capture=false;base.OnMouseUp(e);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;int y=Height/2;using(var pen=new Pen(Color.FromArgb(110,127,137),5))g.DrawLine(pen,8,y,Math.Max(8,Width-8),y);int x=8+(int)((Width-16)*(position-Minimum)/(double)Math.Max(1,Maximum-Minimum));using(var pen=new Pen(Color.FromArgb(60,198,232),5))g.DrawLine(pen,8,y,x,y);using(var brush=new SolidBrush(Enabled?Color.FromArgb(60,198,232):Color.LightGray))g.FillEllipse(brush,x-5,y-5,10,10);}
}
